#!/usr/bin/env bash
# Generates a fresh release keystore and a matching, git-ignored keystore.properties.
# Use this to replace the key that was previously committed to the repository.
#
# Usage (from the repository root):
#   ./scripts/generate-release-keystore.sh
#
# The generated files are never committed: *.keystore and keystore.properties are
# ignored by .gitignore. Back up both the keystore and its password somewhere safe;
# if they are lost you cannot publish updates for this app.

set -euo pipefail

KEYSTORE_PATH="${1:-app/release.keystore}"
ALIAS="${2:-docscanner}"
DNAME="${3:-CN=DocScanner, OU=Mobile, O=DocScanner, L=Unknown, ST=Unknown, C=IN}"

if [ -e "$KEYSTORE_PATH" ]; then
  echo "$KEYSTORE_PATH already exists. Remove it first if you really want a new key." >&2
  exit 1
fi

PASSWORD="$(head -c 32 /dev/urandom | base64 | tr -d '=+/' | cut -c1-32)"

KEYTOOL="${JAVA_HOME:+$JAVA_HOME/bin/}keytool"

"$KEYTOOL" -genkeypair \
  -keystore "$KEYSTORE_PATH" \
  -alias "$ALIAS" \
  -keyalg RSA \
  -keysize 4096 \
  -validity 10000 \
  -storepass "$PASSWORD" \
  -keypass "$PASSWORD" \
  -dname "$DNAME"

umask 077
cat > keystore.properties <<EOF
# Generated by scripts/generate-release-keystore.sh. Never commit this file.
storeFile=$KEYSTORE_PATH
storePassword=$PASSWORD
keyAlias=$ALIAS
keyPassword=$PASSWORD
EOF

echo
echo "Created $KEYSTORE_PATH and keystore.properties."
echo "Back both files up now. Losing them makes future updates impossible."
echo "Users on the old key must uninstall and reinstall the app."
